import { useState, useEffect } from "react";

function MyPortfolio({ portfolioClicked }){

    const [header,setHeader] = useState(<h1 className="port--section--title">My Projects</h1>);

    function LetterByLetterText({ text, delay }) {
            const [displayedText, setDisplayedText] = useState('');
            const [index, setIndex] = useState(0);

            useEffect(() => {
                if (index < text.length) {
                const timeout = setTimeout(() => {
                    setDisplayedText(prevText => prevText + text[index]);
                    setIndex(prevIndex => prevIndex + 1);
                }, delay);

                return () => clearTimeout(timeout);
                }
            }, [text, index, delay]);

        return <span>{displayedText}</span>;
        }

    useEffect(() => {
        if (portfolioClicked) {
            setHeader(<LetterByLetterText text="My Projects" delay={100} />);
        }
    }, [portfolioClicked]);

    return (
        <section id="MyPortfolio" className="port--section">
            <div className="port--section--header">
                {header}
            </div>
            <div className="port--projects">
            <div className="project p1">
                <img src="./img/piccomp.jpg" alt="Project 1" className="project--image" />
                <div className="project--text">
                <h2>Project 1</h2>
                <p>Description for Project 1 goes here.</p>
                </div>
            </div>

            <div className="project reverse p2">
                <img src="./img/piccomp.jpg" alt="Project 2" className="project--image" />
                <div className="project--text">
                <h2>Project 2</h2>
                <p>Description for Project 2 goes here.</p>
                </div>
            </div>

            <div className="project p1">
                <img src="./img/piccomp.jpg" alt="Project 3" className="project--image" />
                <div className="project--text">
                <h2>Project 3</h2>
                <p>Description for Project 3 goes here.</p>
                </div>
            </div>
            </div>
        </section>
    )
}

export default MyPortfolio;
